class Commando < Formula
  desc "Colorful TUI that turns a command's man page into a form for its options"
  homepage "https://github.com/lonedevel/commando"
  license "Apache-2.0"

  head do
    url "https://github.com/lonedevel/commando.git", branch: "main"
    depends_on "go" => :build
  end

  # Generated by scripts/update-formula.sh from the release's checksums.txt.
  on_macos do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.17.0/commando_0.17.0_darwin_arm64.tar.gz"
      sha256 "7aa8f0d6d99ff7104ee4dc626ad4fc3e7de1e6bafabb58877f73333ab65ad73d"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.17.0/commando_0.17.0_darwin_amd64.tar.gz"
      sha256 "d0dcdd56b8fb849d0872c3e51c31ac1e81ce3cc77fd49fd019bdc3a40e9ad3a0"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.17.0/commando_0.17.0_linux_arm64.tar.gz"
      sha256 "6fb69f383b7ccb178fb72f46a06a4b7b074574df5ae11c0d29b674633f10b045"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.17.0/commando_0.17.0_linux_amd64.tar.gz"
      sha256 "d1845f6a06918176c00d25eab390bb1580265202109012e853c55d2c21103555"
    end
  end

  def install
    if build.head?
      system "go", "build", *std_go_args(ldflags: "-s -w -X main.version=#{version}"), "./cmd/commando"
    else
      bin.install "commando"
    end
  end

  def caveats
    <<~EOS
      To edit the command you're typing with Ctrl-X Ctrl-O, add to your shell config:
        zsh:  eval "$(commando --init zsh)"
        bash: eval "$(commando --init bash)"
        fish: commando --init fish | source
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/commando --version")
    assert_match "bindkey", shell_output("#{bin}/commando --init zsh")

    # Parse a manual without needing a terminal.
    ENV["COMMANDO_CACHE_DIR"] = testpath/"cache"
    output = shell_output("#{bin}/commando --dump --no-cache ls")
    assert_match "\"names\"", output
  end
end
